import{_ as n,I as s,o,c as d,b6 as t,J as r}from"./chunks/framework.BUXTSoD9.js";const f=JSON.parse('{"title":"Visualisation de données et tableaux de bord","description":"","frontmatter":{},"headers":[],"relativePath":"fr-fr/appendix/5-data/data-visualization.md","filePath":"fr-fr/appendix/5-data/data-visualization.md"}'),l={name:"fr-fr/appendix/5-data/data-visualization.md"};function u(p,e,c,h,m,b){const i=s("ChartTypeSelectorDemo"),a=s("DashboardLayoutDemo");return o(),d("div",null,[e[0]||(e[0]=t('<h1 id="visualisation-de-donnees-et-tableaux-de-bord" tabindex="-1">Visualisation de données et tableaux de bord <a class="header-anchor" href="#visualisation-de-donnees-et-tableaux-de-bord" aria-label="Permalink to “Visualisation de données et tableaux de bord”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Avant-propos</p><p><strong>Un bon graphique vaut mieux que mille lignes de données.</strong> La visualisation de données consiste à transformer des chiffres abstraits en expressions visuelles intuitives, permettant de comprendre l&#39;histoire derrière les données en quelques secondes. Des graphiques Excel aux écrans de supervision Grafana, la visualisation est omniprésente.</p></div><p><strong>Que allez-vous apprendre dans cet article ?</strong></p><p>À l&#39;issue de ce chapitre, vous serez capable de :</p><ul><li><strong>Choisir les bons graphiques</strong> : sélectionner le type de graphique le plus adapté à l&#39;objectif des données</li><li><strong>Principes de visualisation</strong> : maîtriser les principes fondamentaux de la conception de visualisations de données</li><li><strong>Conception de tableaux de bord</strong> : comprendre les modèles de disposition des différents types de tableaux de bord</li><li><strong>Écosystème d&#39;outils</strong> : connaître le positionnement et la sélection des principaux outils de visualisation</li><li><strong>Pièges courants</strong> : éviter les graphiques trompeurs et les erreurs de visualisation fréquentes</li></ul><table tabindex="0"><thead><tr><th>Chapitre</th><th>Contenu</th><th>Concepts clés</th></tr></thead><tbody><tr><td><strong>Chapitre 1</strong></td><td>Choix du type de graphique</td><td>Comparaison, tendance, proportion, distribution, relation</td></tr><tr><td><strong>Chapitre 2</strong></td><td>Principes de conception visuelle</td><td>Ratio données-encre, cohérence, lisibilité</td></tr><tr><td><strong>Chapitre 3</strong></td><td>Disposition des tableaux de bord</td><td>Vue d&#39;ensemble, comparaison, exploration, temps réel</td></tr><tr><td><strong>Chapitre 4</strong></td><td>Sélection des outils</td><td>ECharts, D3, Grafana, Metabase</td></tr><tr><td><strong>Chapitre 5</strong></td><td>Pièges courants</td><td>Axe tronqué, graphique en camembert 3D, mauvais usage des couleurs</td></tr></tbody></table><hr><h2 id="_0-vue-d-ensemble-pourquoi-la-visualisation" tabindex="-1">0. Vue d&#39;ensemble : Pourquoi la visualisation ? <a class="header-anchor" href="#_0-vue-d-ensemble-pourquoi-la-visualisation" aria-label="Permalink to “0. Vue d&#39;ensemble : Pourquoi la visualisation ?”">​</a></h2><p>Le cerveau humain traite l&#39;information visuelle beaucoup plus rapidement que le texte. Un graphique en courbes vous permet de voir rapidement que « les ventes du mois dernier ont baissé », alors que la même information présentée dans un tableau nécessiterait une comparaison ligne par ligne pour tirer cette conclusion.</p><p>La valeur essentielle de la visualisation :</p><ul><li><strong>Détecter des modèles</strong> : tendances, cycles, valeurs aberrantes sont immédiatement visibles dans un graphique</li><li><strong>Aider à la décision</strong> : permettre même aux non-techniciens de comprendre les données et de participer aux décisions</li><li><strong>Efficacité de communication</strong> : un graphique vaut mille mots, réduisant les ambiguïtés dans l&#39;interprétation des données</li></ul><div class="tip custom-block"><p class="custom-block-title">Visualisation ≠ Beau</p><p>L&#39;objectif de la visualisation est de <strong>transmettre l&#39;information</strong>, pas de faire de l&#39;esbroufe. Un diagramme en barres sobre mais précis est bien plus précieux qu&#39;un graphique 3D voyant mais difficile à comprendre.</p></div><hr><h2 id="_1-choix-du-type-de-graphique-le-bon-graphique-pour-raconter-la-bonne-histoire" tabindex="-1">1. Choix du type de graphique : le bon graphique pour raconter la bonne histoire <a class="header-anchor" href="#_1-choix-du-type-de-graphique-le-bon-graphique-pour-raconter-la-bonne-histoire" aria-label="Permalink to “1. Choix du type de graphique : le bon graphique pour raconter la bonne histoire”">​</a></h2><p>La première étape pour choisir un graphique n&#39;est pas « quel graphime j&#39;aime », mais « quelle information je veux transmettre ». Différents objectifs de données correspondent à différents types de graphiques optimaux.</p>',15)),r(i),e[1]||(e[1]=t('<h3 id="tableau-de-reference-pour-le-choix-des-graphiques" tabindex="-1">Tableau de référence pour le choix des graphiques <a class="header-anchor" href="#tableau-de-reference-pour-le-choix-des-graphiques" aria-label="Permalink to “Tableau de référence pour le choix des graphiques”">​</a></h3><table tabindex="0"><thead><tr><th>Objectif des données</th><th>Graphique recommandé</th><th>Déconseillé</th><th>Raison</th></tr></thead><tbody><tr><td>Comparer des valeurs</td><td>Diagramme en barres, diagramme en barres horizontales</td><td>Camembert</td><td>L&#39;œil humain est plus sensible aux différences de longueur qu&#39;aux différences d&#39;angle</td></tr><tr><td>Montrer une tendance</td><td>Graphique en courbes, graphique en aires</td><td>Diagramme en barres</td><td>La continuité de la ligne suggère la continuité temporelle</td></tr><tr><td>Montrer une proportion</td><td>Camembert (≤5 catégories), barres empilées</td><td>Camembert 3D</td><td>La perspective 3D déforme les proportions de surface</td></tr><tr><td>Montrer une distribution</td><td>Histogramme, boîte à moustaches</td><td>Graphique en courbes</td><td>La distribution nécessite de voir la fréquence, pas la tendance</td></tr><tr><td>Montrer une relation</td><td>Nuage de points, graphique à bulles</td><td>Diagramme en barres</td><td>La relation entre deux variables continues nécessite un espace bidimensionnel</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Une règle de décision simple</p><ul><li><strong>Une variable</strong> → Histogramme (distribution) ou carte de chiffres (KPI)</li><li><strong>Deux variables</strong> → Graphique en courbes (temps vs valeur) ou nuage de points (valeur vs valeur)</li><li><strong>Plusieurs catégories</strong> → Diagramme en barres (comparaison) ou camembert (proportion, ≤5 catégories)</li><li><strong>Multidimensionnel</strong> → Radar ou coordonnées parallèles</li></ul></div><hr><h2 id="_2-principes-de-conception-visuelle-laisser-les-donnees-parler" tabindex="-1">2. Principes de conception visuelle : laisser les données parler <a class="header-anchor" href="#_2-principes-de-conception-visuelle-laisser-les-donnees-parler" aria-label="Permalink to “2. Principes de conception visuelle : laisser les données parler”">​</a></h2><p>Une bonne visualisation n&#39;est pas « belle », mais « compréhensible ». Plusieurs principes classiques formulés par Edward Tufte dans <em>The Visual Display of Quantitative Information</em> restent une référence importante en conception de visualisation.</p><table tabindex="0"><thead><tr><th>Principe</th><th>Description</th><th>Contre-exemple</th></tr></thead><tbody><tr><td>Ratio données-encre</td><td>La proportion d&#39;« encre » utilisée pour afficher les données dans le graphique doit être aussi élevée que possible</td><td>Trop de lignes de grille, éléments décoratifs</td></tr><tr><td>Minimiser les éléments non liés aux données</td><td>Supprimer les éléments visuels qui ne transmettent pas d&#39;information</td><td>Effets 3D, ombres, arrière-plans en dégradé</td></tr><tr><td>Échelle cohérente</td><td>Les axes partent de zéro, les graduations sont uniformes ; si l&#39;axe est tronqué, il faut l&#39;indiquer explicitement</td><td>L&#39;axe Y commence à 95 sans indication</td></tr><tr><td>Usage raisonnable des couleurs</td><td>Utiliser les couleurs pour coder l&#39;information, pas pour décorer</td><td>Arc-en-ciel pour des données ordinales</td></tr><tr><td>Annotations claires</td><td>Titre, étiquettes d&#39;axes, légende, unités — aucun ne doit manquer</td><td>Pas d&#39;unité, pas de plage temporelle</td></tr></tbody></table><h3 id="_2-1-le-ratio-donnees-encre-data-ink-ratio" tabindex="-1">2.1 Le ratio données-encre (Data-Ink Ratio) <a class="header-anchor" href="#_2-1-le-ratio-donnees-encre-data-ink-ratio" aria-label="Permalink to “2.1 Le ratio données-encre (Data-Ink Ratio)”">​</a></h3><blockquote><p>La proportion d&#39;« encre » utilisée pour exprimer les données dans un graphique par rapport à l&#39;« encre » totale doit être aussi élevée que possible.</p></blockquote><p>En termes simples : <strong>supprimez tout élément qui ne transmet pas d&#39;information</strong>.</p><table tabindex="0"><thead><tr><th>À supprimer</th><th>À conserver</th></tr></thead><tbody><tr><td>Effets 3D, ombres, dégradés</td><td>Points de données, étiquettes d&#39;axes</td></tr><tr><td>Lignes de grille superflues</td><td>Lignes de référence clés (ex. valeur cible)</td></tr><tr><td>Icônes décoratives</td><td>Légende (lorsqu&#39;il y a plusieurs séries)</td></tr><tr><td>Couleurs d&#39;arrière-plan voyantes</td><td>Titre et unités clairs</td></tr></tbody></table><h3 id="_2-2-principe-de-coherence" tabindex="-1">2.2 Principe de cohérence <a class="header-anchor" href="#_2-2-principe-de-coherence" aria-label="Permalink to “2.2 Principe de cohérence”">​</a></h3><ul><li><strong>Couleurs cohérentes</strong> : une même dimension utilise la même couleur dans tous les graphiques, par exemple « revenus » toujours en bleu</li><li><strong>Échelles cohérentes</strong> : les axes doivent si possible commencer à 0, sauf raison valable et annotation explicite</li><li><strong>Temps cohérent</strong> : les intervalles de l&#39;axe temporel doivent être uniformes, ne pas représenter des points temporels inégaux comme s&#39;ils étaient équidistants</li></ul><h3 id="_2-3-principe-de-lisibilite" tabindex="-1">2.3 Principe de lisibilité <a class="header-anchor" href="#_2-3-principe-de-lisibilite" aria-label="Permalink to “2.3 Principe de lisibilité”">​</a></h3><ul><li><strong>Le titre doit exprimer une conclusion</strong> : pas « Ventes mensuelles », mais « Les ventes baissent depuis 3 mois consécutifs »</li><li><strong>Annoter les points clés</strong> : ajouter des annotations aux valeurs aberrantes et aux points d&#39;inflexion pour guider l&#39;attention du lecteur</li><li><strong>Maîtriser la densité d&#39;information</strong> : un graphique doit transmettre 1 à 2 messages essentiels, ne pas tout surcharger</li></ul><div class="tip custom-block"><p class="custom-block-title">Trois règles pour l&#39;utilisation des couleurs</p><ol><li><strong>Même indicateur, même couleur</strong> : les revenus sont toujours en bleu dans tous les graphiques, ne pas alterner entre bleu et vert</li><li><strong>Données ordinales en dégradé</strong> : température du froid au chaud en dégradé bleu → rouge, ne pas utiliser des couleurs discrètes</li><li><strong>Penser à l&#39;accessibilité daltonienne</strong> : environ 8 % des hommes ont un daltonisme rouge-vert, éviter de distinguer les informations clés uniquement par rouge et vert</li></ol></div><hr><h2 id="_3-disposition-des-tableaux-de-bord-differents-scenarios-differents-modeles" tabindex="-1">3. Disposition des tableaux de bord : différents scénarios, différents modèles <a class="header-anchor" href="#_3-disposition-des-tableaux-de-bord-differents-scenarios-differents-modeles" aria-label="Permalink to “3. Disposition des tableaux de bord : différents scénarios, différents modèles”">​</a></h2><p>Un tableau de bord (Dashboard) est une combinaison organique de plusieurs graphiques. Un bon tableau de bord ne se contente pas d&#39;empiler des graphiques, il choisit un modèle de disposition adapté au contexte d&#39;utilisation.</p>',19)),r(a),e[2]||(e[2]=t('<h3 id="quatre-modeles-de-disposition-courants" tabindex="-1">Quatre modèles de disposition courants <a class="header-anchor" href="#quatre-modeles-de-disposition-courants" aria-label="Permalink to “Quatre modèles de disposition courants”">​</a></h3><table tabindex="0"><thead><tr><th>Modèle de disposition</th><th>Structure essentielle</th><th>Scénario d&#39;utilisation</th><th>Points de conception</th></tr></thead><tbody><tr><td>Vue d&#39;ensemble globale</td><td>Cartes KPI + graphique de tendance + tableau détaillé</td><td>Rapports quotidiens pour la direction, tableau de bord des opérations</td><td>Indicateurs clés tout en haut, visibles en un coup d&#39;œil</td></tr><tr><td>Analyse comparative</td><td>Disposition symétrique gauche-droite</td><td>Tests A/B, analyse année sur année</td><td>Garder les dimensions de comparaison cohérentes, mettre en évidence les différences</td></tr><tr><td>Analyse exploratoire</td><td>Déploiement progressif du résumé au détail</td><td>Analyse des ventes, analyse du comportement utilisateur</td><td>Supporter l&#39;interaction au clic, exploration par niveaux</td></tr><tr><td>Supervision en temps réel</td><td>Grands chiffres + courbe temps réel + état des alertes</td><td>Écran du 11 novembre, supervision de serveurs</td><td>Rafraîchissement automatique, fond sombre, adapté à la projection</td></tr></tbody></table><h3 id="_5-principes-de-conception-de-tableaux-de-bord" tabindex="-1">5 principes de conception de tableaux de bord <a class="header-anchor" href="#_5-principes-de-conception-de-tableaux-de-bord" aria-label="Permalink to “5 principes de conception de tableaux de bord”">​</a></h3><ol><li><strong>D&#39;abord demander « qui regarde »</strong> : le PDG voit les indicateurs stratégiques, les opérations voient les indicateurs de processus, les ingénieurs voient les indicateurs techniques</li><li><strong>Règle des 5 secondes</strong> : l&#39;utilisateur doit comprendre l&#39;information essentielle du tableau de bord en 5 secondes</li><li><strong>Hiérarchie de l&#39;information</strong> : le plus important en haut à gauche, le secondaire en bas</li><li><strong>Réduire le défilement</strong> : afficher le contenu essentiel sur un seul écran, éviter que l&#39;utilisateur doive faire défiler pour voir les données clés</li><li><strong>Espace blanc</strong> : ne pas remplir chaque centimètre, un espacement adéquat rend la lecture plus confortable</li></ol><div class="tip custom-block"><p class="custom-block-title">Tableau de bord vs Rapport</p><ul><li><strong>Tableau de bord</strong> : temps réel/quasi temps réel, interactif, orienté supervision et décision rapide</li><li><strong>Rapport</strong> : généré périodiquement (journalier/hebdomadaire/mensuel), statique, orienté analyse détaillée et archivage</li></ul><p>Les deux ne se substituent pas, ils se complètent. Le tableau de bord détecte les problèmes, le rapport les analyse en profondeur.</p></div><hr><h2 id="_4-selection-des-outils-des-bibliotheques-de-code-aux-plateformes-bi" tabindex="-1">4. Sélection des outils : des bibliothèques de code aux plateformes BI <a class="header-anchor" href="#_4-selection-des-outils-des-bibliotheques-de-code-aux-plateformes-bi" aria-label="Permalink to “4. Sélection des outils : des bibliothèques de code aux plateformes BI”">​</a></h2><p>Les outils de visualisation peuvent être classés en trois niveaux : bibliothèques de graphiques au niveau du code, bibliothèques de graphiques pour l&#39;analyse de données, plateformes BI. Le choix dépend de la complexité des besoins, des exigences d&#39;interactivité et des compétences techniques de l&#39;équipe.</p><h3 id="_4-1-bibliotheques-de-graphiques-au-niveau-du-code" tabindex="-1">4.1 Bibliothèques de graphiques au niveau du code <a class="header-anchor" href="#_4-1-bibliotheques-de-graphiques-au-niveau-du-code" aria-label="Permalink to “4.1 Bibliothèques de graphiques au niveau du code”">​</a></h3><table tabindex="0"><thead><tr><th>Outil</th><th>Langage/Plateforme</th><th>Caractéristiques</th><th>Scénario d&#39;utilisation</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>Prêt à l&#39;emploi, types de graphiques riches, documentation en chinois complète</td><td>Graphiques intégrés dans les systèmes métier</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>Bas niveau flexible, personnalisable pour tout effet de visualisation</td><td>Visualisation de données hautement personnalisée</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>Léger et simple, prise en main rapide</td><td>Besoins simples en graphiques</td></tr><tr><td>Matplotlib</td><td>Python</td><td>Bibliothèque standard de calcul scientifique, graphiques statiques</td><td>Analyse de données, graphiques pour publications</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>Graphiques interactifs, support 3D</td><td>Exploration de données, Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-plateformes-bi-sans-code-low-code" tabindex="-1">4.2 Plateformes BI (sans code/low-code) <a class="header-anchor" href="#_4-2-plateformes-bi-sans-code-low-code" aria-label="Permalink to “4.2 Plateformes BI (sans code/low-code)”">​</a></h3><table tabindex="0"><thead><tr><th>Outil</th><th>Positionnement</th><th>Avantage principal</th><th>Équipe cible</th></tr></thead><tbody><tr><td>Grafana</td><td>Visualisation de supervision</td><td>Bon support des séries temporelles, intégration d&#39;alertes</td><td>Équipes Ops/SRE</td></tr><tr><td>Metabase</td><td>BI léger</td><td>Open source et gratuit, graphiques à partir de SQL</td><td>Création rapide pour PME</td></tr><tr><td>Apache Superset</td><td>BI entreprise</td><td>Open source, support de sources Big Data</td><td>Entreprises avec une équipe data</td></tr><tr><td>Tableau</td><td>BI commercial</td><td>Opération par glisser-déposer, excellents résultats visuels</td><td>Analystes métier</td></tr><tr><td>Power BI</td><td>BI commercial</td><td>Bonne intégration avec l&#39;écosystème Microsoft</td><td>Entreprises utilisant la stack Microsoft</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Conseils de sélection</p><ul><li><strong>Développeurs intégrant des graphiques dans un produit</strong> → ECharts (bon écosystème chinois) ou Chart.js (scénarios simples)</li><li><strong>Analystes de données en exploration</strong> → Plotly + Jupyter ou Metabase</li><li><strong>Écran de supervision Ops</strong> → Grafana (standard de fait)</li><li><strong>Équipes métier en auto-analyse</strong> → Metabase (open source) ou Tableau (commercial)</li><li><strong>Besoin de personnalisation avancée</strong> → D3.js (courbe d&#39;apprentissage raide, mais la plus malléable)</li></ul></div><hr><h2 id="_5-pieges-courants-ces-graphiques-vous-mentent" tabindex="-1">5. Pièges courants : ces graphiques vous mentent <a class="header-anchor" href="#_5-pieges-courants-ces-graphiques-vous-mentent" aria-label="Permalink to “5. Pièges courants : ces graphiques vous mentent”">​</a></h2><p>La visualisation de données est un outil à double tranchant : bien utilisée, elle révèle la vérité ; mal utilisée, elle crée des illusions. Voici les pièges de visualisation les plus courants que tout professionnel des données devrait savoir identifier.</p><h3 id="_5-1-axe-tronque" tabindex="-1">5.1 Axe tronqué <a class="header-anchor" href="#_5-1-axe-tronque" aria-label="Permalink to “5.1 Axe tronqué”">​</a></h3><p>Changer le point de départ de l&#39;axe Y de 0 à un nombre élevé rend les petites différences ressemblant à des variations énormes.</p><table tabindex="0"><thead><tr><th>Scénario</th><th>Différence réelle</th><th>Perception visuelle</th></tr></thead><tbody><tr><td>Axe Y à partir de 0</td><td>Produit A : 98, Produit B : 95</td><td>Différence minime</td></tr><tr><td>Axe Y à partir de 90</td><td>Mêmes données</td><td>A semble plusieurs fois supérieur à B</td></tr></tbody></table><p><strong>Quand est-il acceptable de tronquer ?</strong> Lorsque la valeur absolue des données est grande mais les variations faibles (ex. cours de bourse passant de 100 à 105), la troncation est raisonnable, mais elle doit être explicitement annotée.</p><h3 id="_5-2-le-piege-de-la-perspective-des-camemberts-3d" tabindex="-1">5.2 Le piège de la perspective des camemberts 3D <a class="header-anchor" href="#_5-2-le-piege-de-la-perspective-des-camemberts-3d" aria-label="Permalink to “5.2 Le piège de la perspective des camemberts 3D”">​</a></h3><p>La perspective 3D rend les secteurs proches de l&#39;observateur plus grands. Un secteur de 25 % peut sembler représenter 35 % en vue 3D.</p><p><strong>Solution</strong> : ne jamais utiliser de camembert 3D. Utilisez un camembert classique ou un graphique en anneau, ou simplement un diagramme en barres.</p><h3 id="_5-3-mauvais-usage-des-couleurs" tabindex="-1">5.3 Mauvais usage des couleurs <a class="header-anchor" href="#_5-3-mauvais-usage-des-couleurs" aria-label="Permalink to “5.3 Mauvais usage des couleurs”">​</a></h3><table tabindex="0"><thead><tr><th>Mauvaise pratique</th><th>Bonne pratique</th></tr></thead><tbody><tr><td>Utiliser rouge et vert pour les données</td><td>Utiliser des palettes daltoniennes comme bleu-orange</td></tr><tr><td>Couleur différente pour chaque catégorie</td><td>Même série avec des nuances d&#39;une même couleur</td></tr><tr><td>Coder des données continues en couleur sans légende</td><td>Toujours fournir une légende des couleurs et des annotations de valeurs</td></tr><tr><td>Contraste insuffisant entre fond et couleurs de données</td><td>Assurer un contraste de niveau WCAG AA</td></tr></tbody></table><h3 id="_5-4-autres-erreurs-courantes" tabindex="-1">5.4 Autres erreurs courantes <a class="header-anchor" href="#_5-4-autres-erreurs-courantes" aria-label="Permalink to “5.4 Autres erreurs courantes”">​</a></h3><table tabindex="0"><thead><tr><th>Piège</th><th>Problème</th><th>Correction</th></tr></thead><tbody><tr><td>Double axe Y</td><td>Deux indicateurs sans relation partagent l&#39;axe X, suggérant une causalité</td><td>Séparer en deux graphiques, ou indiquer clairement l&#39;absence de causalité</td></tr><tr><td>Surface trompeuse</td><td>Utiliser le rayon du cercle et non la surface pour représenter une valeur</td><td>Quand la valeur double, la surface doit doubler, pas le rayon</td></tr><tr><td>Axe temporel non uniforme</td><td>Janvier, mars, décembre sont espacés de manière identique</td><td>Disposer selon les proportions temporelles réelles</td></tr><tr><td>Trop de catégories</td><td>Camembert avec 15 secteurs</td><td>Au-delà de 5 catégories, utiliser un diagramme en barres ou regrouper dans « Autres »</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Éthique de la visualisation</p><p>L&#39;objectif de la visualisation est d&#39;<strong>aider à comprendre</strong>, pas de <strong>manipuler la perception</strong>. À chaque fois que vous créez un graphique, demandez-vous :</p><ul><li>Si j&#39;étais le lecteur, ce graphique me ferait-il tirer une conclusion erronée ?</li><li>Suis-je en train de cacher des données défavorables ?</li><li>Les axes, les proportions et les couleurs représentent-ils les données de manière équitable ?</li></ul></div><hr><h2 id="resume" tabindex="-1">Résumé <a class="header-anchor" href="#resume" aria-label="Permalink to “Résumé”">​</a></h2><p>La visualisation de données est le « dernier kilomètre » de la transmission de la valeur des données. La meilleure des analyses, si elle n&#39;est pas correctement comprise, équivaut à aucune analyse.</p><p>Retour sur les points clés de ce chapitre :</p><ol><li><strong>Choisir le bon graphique</strong> : sélectionner le type de graphique selon l&#39;objectif des données (comparaison, tendance, proportion, distribution, relation)</li><li><strong>Principes de conception</strong> : ratio données-encre élevé, cohérence et lisibilité sont les trois principes fondamentaux</li><li><strong>Disposition des tableaux de bord</strong> : les quatre modèles — vue d&#39;ensemble, comparaison, exploration, temps réel — couvrent la plupart des scénarios</li><li><strong>Sélection des outils</strong> : d&#39;ECharts à Grafana, choisir selon les capacités de l&#39;équipe et la complexité des besoins</li><li><strong>Éviter les pièges</strong> : axe tronqué, camembert 3D, mauvais usage des couleurs sont les moyens trompeurs les plus courants</li></ol><h2 id="lectures-complementaires" tabindex="-1">Lectures complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to “Lectures complémentaires”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Le classique de la visualisation par Edward Tufte</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">Documentation officielle ECharts</a> - La bibliothèque de graphiques en chinois la plus populaire</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - Bibliothèque de visualisation bas niveau puissante</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - Standard de fait pour la visualisation de supervision</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - Arbre de décision pour le choix des types de graphiques</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - Outil de palettes de couleurs adaptées au daltonisme</li></ul>',35))])}const v=n(l,[["render",u]]);export{f as __pageData,v as default};
